self.KB_CONTENT["card:754290"]={"id":"card:754290","ty":"card","sourceId":"754290","title":"『訂單變更單建立作業』中的『訂單數量 (TF009)』為何？","ver":"iGP","topic":"變更單","keywords":["變更單","庫存","訂單","用量"],"y":"other","answer":"* [F2]各庫庫存量查詢。* [F3]可用量查詢（可用量：現有存量-已受訂量）。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
