self.KB_CONTENT["card:782077"]={"id":"card:782077","ty":"card","sourceId":"782077","title":"『預購/售外匯資料建立作業』中的『銀行代號 (TR001)』為何？","ver":"GP4以上","topic":"銀行","keywords":["銀行","帳號"],"y":"other","answer":"* 為公司的往來銀行，可點選或按[F2]銀行帳號資料查詢。* 輸入完銀行代號會自動顯示該銀行代號之銀行簡稱、銀行帳號欄位資料，不可空白。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
